import { TODAY } from "../data/seed";
import type { Bill, Invoice, Recurrence } from "../types";
import { addDays } from "./format";
import { isUnpaid } from "./invoices";

/** Supported forecast lengths in days. */
export type HorizonDays = 30 | 60 | 90;

/** A single expected inflow or outflow on a specific date. `amountINR` is always positive. */
export type CashEvent = {
  date: string;
  type: "invoice" | "bill";
  description: string;
  amountINR: number;
  direction: "in" | "out";
  sourceId: string;
};

/** One calendar day of the forecast with its aggregated flows and resulting closing balance. */
export type ForecastDay = {
  date: string;
  inflowINR: number;
  outflowINR: number;
  balanceINR: number;
  events: CashEvent[];
};

/** Full forecast: one row per day, a flat chronological ledger, and summary figures. */
export type CashForecast = {
  horizonDays: HorizonDays;
  startDate: string;
  days: ForecastDay[];
  events: CashEvent[];
  lowestBalanceINR: number;
  firstNegativeDate: string | null;
};

const VALID_HORIZONS: readonly number[] = [30, 60, 90];
const STEP_MONTHS: Record<Recurrence, number> = { "one-time": 0, monthly: 1, quarterly: 3, yearly: 12 };
const DIRECTION_ORDER = { in: 0, out: 1 } as const;

/**
 * Returns the occurrence of `dueDate` shifted by `monthsAhead` months.
 * The day-of-month is clamped to the last day of the target month (e.g. Jan 31 + 1 month = Feb 28/29).
 */
function occurrenceOn(dueDate: string, monthsAhead: number): string {
  const [year, month, day] = dueDate.split("-").map(Number);
  const monthIndex = month - 1 + monthsAhead;
  const targetYear = year + Math.floor(monthIndex / 12);
  const targetMonth = monthIndex % 12;
  const lastDay = new Date(Date.UTC(targetYear, targetMonth + 1, 0)).getUTCDate();
  const targetDay = Math.min(day, lastDay);
  return `${String(targetYear).padStart(4, "0")}-${String(targetMonth + 1).padStart(2, "0")}-${String(targetDay).padStart(2, "0")}`;
}

/**
 * Due dates of a bill that fall inside [startDate, endDate].
 * Occurrences before startDate are ignored, except that an overdue bill whose most recent
 * past occurrence predates startDate is expected on startDate instead.
 */
function billDates(bill: Bill, startDate: string, endDate: string): string[] {
  const step = STEP_MONTHS[bill.recurrence];
  const [dueYear, dueMonth] = bill.dueDate.split("-").map(Number);
  const [startYear, startMonth] = startDate.split("-").map(Number);
  const monthsElapsed = (startYear - dueYear) * 12 + (startMonth - dueMonth);
  // Begin one step before the first possibly-relevant occurrence so the latest past one is seen.
  const firstIndex = step > 0 ? Math.max(0, Math.floor(monthsElapsed / step) - 1) : 0;

  const dates: string[] = [];
  let latestPast: string | null = null;
  // One-time bills (step 0) produce only occurrence 0.
  for (let index = firstIndex; step > 0 || index === 0; index++) {
    const date = occurrenceOn(bill.dueDate, index * step);
    if (date > endDate) break;
    if (date < startDate) {
      latestPast = date;
    } else {
      dates.push(date);
    }
  }

  if (bill.status === "overdue" && latestPast !== null) {
    dates.unshift(startDate);
  }
  return dates;
}

/**
 * Projects daily cash balances over `horizonDays` starting at `startDate`.
 *
 * - Inflows: unpaid invoices with status "sent" or "overdue". Any invoice due before startDate is expected on startDate.
 * - Outflows: bills not marked paid, expanded by recurrence (monthly/quarterly/yearly, day-of-month clamped).
 * - Within a day, events are ordered inflows first, then outflows, then by description.
 * - `lowestBalanceINR` is the minimum over all day balances AND the opening `currentCash`.
 * - `firstNegativeDate` is the first day whose balance is below zero, or null.
 * Pure: inputs are not mutated and "today" is never read from the clock.
 *
 * @throws {RangeError} if `horizonDays` is not 30, 60 or 90.
 */
export function calculateCashForecast(
  currentCash: number,
  invoices: Invoice[],
  bills: Bill[],
  horizonDays: HorizonDays,
  startDate: string = TODAY,
): CashForecast {
  if (!VALID_HORIZONS.includes(horizonDays)) {
    throw new RangeError(`Unsupported forecast horizon: ${horizonDays}. Expected 30, 60 or 90.`);
  }
  const endDate = addDays(startDate, horizonDays - 1);

  const invoiceEvents: CashEvent[] = invoices
    .filter((invoice) => isUnpaid(invoice) && (invoice.status === "sent" || invoice.status === "overdue"))
    .map(
      (invoice): CashEvent => ({
        date: invoice.dueDate < startDate ? startDate : invoice.dueDate,
        type: "invoice",
        description: invoice.description,
        amountINR: invoice.amountINR,
        direction: "in",
        sourceId: invoice.id,
      }),
    )
    .filter((event) => event.date <= endDate);

  const billEvents: CashEvent[] = bills
    .filter((bill) => bill.status !== "paid")
    .flatMap((bill) =>
      billDates(bill, startDate, endDate).map(
        (date): CashEvent => ({
          date,
          type: "bill",
          description: bill.name,
          amountINR: bill.amountINR,
          direction: "out",
          sourceId: bill.id,
        }),
      ),
    );

  const events = [...invoiceEvents, ...billEvents].sort(
    (a, b) =>
      a.date.localeCompare(b.date) ||
      DIRECTION_ORDER[a.direction] - DIRECTION_ORDER[b.direction] ||
      a.description.localeCompare(b.description),
  );

  const eventsByDate = new Map<string, CashEvent[]>();
  for (const event of events) {
    eventsByDate.set(event.date, [...(eventsByDate.get(event.date) ?? []), event]);
  }

  const days: ForecastDay[] = [];
  let balanceINR = currentCash;
  for (let index = 0; index < horizonDays; index++) {
    const date = addDays(startDate, index);
    const dayEvents = eventsByDate.get(date) ?? [];
    const inflowINR = dayEvents
      .filter((event) => event.direction === "in")
      .reduce((total, event) => total + event.amountINR, 0);
    const outflowINR = dayEvents
      .filter((event) => event.direction === "out")
      .reduce((total, event) => total + event.amountINR, 0);
    balanceINR += inflowINR - outflowINR;
    days.push({ date, inflowINR, outflowINR, balanceINR, events: dayEvents });
  }

  return {
    horizonDays,
    startDate,
    days,
    events,
    lowestBalanceINR: Math.min(currentCash, ...days.map((day) => day.balanceINR)),
    firstNegativeDate: days.find((day) => day.balanceINR < 0)?.date ?? null,
  };
}


--- src\utils\cashForecast.test.ts ---
import { describe, expect, it } from "vitest";
import { TODAY, bills as seedBills, cashAccounts, invoices as seedInvoices } from "../data/seed";
import type { Bill, Invoice, InvoiceStatus, Recurrence } from "../types";
import { addDays } from "./format";
import { type HorizonDays, calculateCashForecast } from "./cashForecast";

const START = "2025-06-15";

function makeInvoice(overrides: Partial<Invoice> & { id: string; status: InvoiceStatus }): Invoice {
  return {
    clientId: "C-01",
    description: `Invoice ${overrides.id}`,
    amountINR: 10000,
    issueDate: "2025-06-01",
    dueDate: addDays(START, 5),
    ...overrides,
  };
}

function makeBill(
  overrides: Partial<Bill> & { id: string; recurrence: Recurrence; dueDate: string },
): Bill {
  return {
    name: `Bill ${overrides.id}`,
    category: "Test",
    amountINR: 1000,
    status: "upcoming",
    ...overrides,
  };
}

describe("calculateCashForecast", () => {
  it("throws a RangeError for a horizon other than 30, 60 or 90", () => {
    expect(() => calculateCashForecast(0, [], [], 45 as HorizonDays)).toThrow(RangeError);
  });

  it.each([30, 60, 90] as HorizonDays[])("produces %i daily rows from startDate", (horizon) => {
    const forecast = calculateCashForecast(0, [], [], horizon, START);

    expect(forecast.horizonDays).toBe(horizon);
    expect(forecast.startDate).toBe(START);
    expect(forecast.days).toHaveLength(horizon);
    expect(forecast.days[0].date).toBe(START);
    expect(forecast.days[horizon - 1].date).toBe(addDays(START, horizon - 1));
  });

  it("excludes paid invoices", () => {
    const paid = makeInvoice({ id: "INV-P", status: "paid", paidDate: START });
    const forecast = calculateCashForecast(0, [paid], [], 30, START);

    expect(forecast.events).toHaveLength(0);
    expect(forecast.days.every((day) => day.inflowINR === 0)).toBe(true);
  });

  it("excludes draft invoices", () => {
    const draft = makeInvoice({ id: "INV-D", status: "draft" });
    const forecast = calculateCashForecast(0, [draft], [], 30, START);

    expect(forecast.events).toHaveLength(0);
    expect(forecast.days.every((day) => day.inflowINR === 0)).toBe(true);
  });

  it("counts an overdue invoice as an inflow on startDate", () => {
    const overdue = makeInvoice({
      id: "INV-O",
      status: "overdue",
      amountINR: 50000,
      dueDate: addDays(START, -10),
    });
    const forecast = calculateCashForecast(0, [overdue], [], 30, START);

    expect(forecast.days[0].inflowINR).toBe(50000);
    expect(forecast.days[0].balanceINR).toBe(50000);
    expect(forecast.events[0]).toMatchObject({
      date: START,
      type: "invoice",
      direction: "in",
      amountINR: 50000,
      sourceId: "INV-O",
    });
  });

  it("excludes an invoice whose due date falls after the horizon end", () => {
    const late = makeInvoice({ id: "INV-L", status: "sent", dueDate: addDays(START, 30) });
    const forecast = calculateCashForecast(0, [late], [], 30, START);

    expect(forecast.events).toHaveLength(0);
  });

  it("repeats a monthly bill within a 60-day horizon", () => {
    const rent = makeBill({ id: "B-RENT", recurrence: "monthly", dueDate: "2025-06-20" });
    const forecast = calculateCashForecast(0, [], [rent], 60, START);
    const billDates = forecast.events.filter((event) => event.type === "bill").map((event) => event.date);

    expect(billDates).toEqual(["2025-06-20", "2025-07-20"]);
    expect(forecast.days.reduce((total, day) => total + day.outflowINR, 0)).toBe(2000);
  });

  it("places a yearly bill once within a 90-day horizon", () => {
    const insurance = makeBill({ id: "B-INS", recurrence: "yearly", dueDate: "2025-07-01" });
    const forecast = calculateCashForecast(0, [], [insurance], 90, START);
    const billEvents = forecast.events.filter((event) => event.type === "bill");

    expect(billEvents).toHaveLength(1);
    expect(billEvents[0].date).toBe("2025-07-01");
  });

  it("excludes paid bills", () => {
    const paid = makeBill({ id: "B-PAID", recurrence: "one-time", dueDate: START, status: "paid" });
    const forecast = calculateCashForecast(0, [], [paid], 30, START);

    expect(forecast.events).toHaveLength(0);
    expect(forecast.days.every((day) => day.outflowINR === 0)).toBe(true);
  });

  it("aggregates same-date events and orders the inflow before the outflow", () => {
    // The bill sorts first alphabetically, so only the inflow-first rule puts the invoice ahead of it.
    const invoice = makeInvoice({
      id: "INV-Z",
      status: "sent",
      description: "Zed project",
      amountINR: 10000,
      dueDate: "2025-06-20",
    });
    const bill = makeBill({
      id: "B-A",
      name: "Aardvark rent",
      recurrence: "one-time",
      dueDate: "2025-06-20",
      amountINR: 4000,
    });
    const forecast = calculateCashForecast(100000, [invoice], [bill], 30, START);
    const day = forecast.days.find((row) => row.date === "2025-06-20");

    expect(day).toBeDefined();
    expect(day?.inflowINR).toBe(10000);
    expect(day?.outflowINR).toBe(4000);
    expect(day?.balanceINR).toBe(106000);
    expect(day?.events.map((event) => event.direction)).toEqual(["in", "out"]);
    expect(forecast.events.map((event) => event.sourceId)).toEqual(["INV-Z", "B-A"]);
  });

  it("sets firstNegativeDate and lowestBalanceINR when the balance goes negative", () => {
    const bill = makeBill({ id: "B-BIG", recurrence: "one-time", dueDate: "2025-06-18", amountINR: 5000 });
    const forecast = calculateCashForecast(1000, [], [bill], 30, START);

    expect(forecast.firstNegativeDate).toBe("2025-06-18");
    expect(forecast.lowestBalanceINR).toBe(-4000);
    expect(forecast.days.find((day) => day.date === "2025-06-17")?.balanceINR).toBe(1000);
    expect(forecast.days.find((day) => day.date === "2025-06-18")?.balanceINR).toBe(-4000);
  });

  it("reports firstNegativeDate as null when the balance never goes negative", () => {
    const bill = makeBill({ id: "B-OK", recurrence: "one-time", dueDate: "2025-06-18", amountINR: 500 });
    const forecast = calculateCashForecast(1000, [], [bill], 30, START);

    expect(forecast.firstNegativeDate).toBeNull();
    expect(forecast.lowestBalanceINR).toBe(500);
  });

  it("computes balances from the inputs: changing currentCash shifts every balance equally", () => {
    const invoice = makeInvoice({ id: "INV-S", status: "sent", dueDate: "2025-06-25" });
    const bill = makeBill({ id: "B-S", recurrence: "monthly", dueDate: "2025-06-22" });

    const low = calculateCashForecast(100000, [invoice], [bill], 60, START);
    const high = calculateCashForecast(150000, [invoice], [bill], 60, START);

    expect(high.days).toHaveLength(low.days.length);
    low.days.forEach((day, index) => {
      expect(high.days[index].balanceINR - day.balanceINR).toBe(50000);
    });
    expect(high.lowestBalanceINR - low.lowestBalanceINR).toBe(50000);
  });

  it("matches the seed data: 30 rows and day-0 balance equals opening plus day-0 net", () => {
    const currentCash = cashAccounts.reduce((total, account) => total + account.balanceINR, 0);
    const forecast = calculateCashForecast(currentCash, seedInvoices, seedBills, 30);
    const day0 = forecast.days[0];

    expect(forecast.days).toHaveLength(30);
    expect(day0.date).toBe(TODAY);
    expect(day0.balanceINR).toBe(currentCash + day0.inflowINR - day0.outflowINR);
  });
});


--- src\utils\format.ts ---
const MS_PER_DAY = 86_400_000;

/**
 * Formats an INR amount with ₹ and Indian digit grouping.
 * e.g. 1250000 -> "₹12,50,000", 125000 -> "₹1,25,000", -4500 -> "-₹4,500"
 */
export function formatINR(amount: number): string {
  const sign = amount < 0 ? "-" : "";
  const whole = Math.round(Math.abs(amount)).toString();

  if (whole.length <= 3) {
    return `${sign}₹${whole}`;
  }

  const last3 = whole.slice(-3);
  const head = whole.slice(0, -3);
  // Group the leading digits in pairs, e.g. "1250" -> "12,50".
  const grouped = head.replace(/\B(?=(\d{2})+(?!\d))/g, ",");
  return `${sign}₹${grouped},${last3}`;
}

/** Whole calendar days from `from` to `to` (both "YYYY-MM-DD"). Negative if `to` is earlier. */
export function daysBetween(from: string, to: string): number {
  const start = Date.parse(`${from}T00:00:00Z`);
  const end = Date.parse(`${to}T00:00:00Z`);
  return Math.round((end - start) / MS_PER_DAY);
}

/** Adds a number of calendar days to a "YYYY-MM-DD" date and returns "YYYY-MM-DD". */
export function addDays(iso: string, days: number): string {
  const date = new Date(`${iso}T00:00:00Z`);
  date.setUTCDate(date.getUTCDate() + days);
  return date.toISOString().slice(0, 10);
}

/** Formats "YYYY-MM-DD" for display, e.g. "15 Jun 2025". */
export function formatDate(iso: string): string {
  return new Date(`${iso}T00:00:00Z`).toLocaleDateString("en-IN", {
    day: "2-digit",
    month: "short",
    year: "numeric",
    timeZone: "UTC",
  });
}


--- src\utils\invoices.ts ---
import type { Client, FollowUp, Invoice } from "../types";
import { addDays } from "./format";

export interface ClientBalance {
  client: Client;
  outstandingINR: number;
  invoiceCount: number;
}

const REMINDER_WINDOW_DAYS = 14;

/** True for every status except "paid" (draft, sent, overdue). */
export function isUnpaid(invoice: Invoice): boolean {
  return invoice.status !== "paid";
}

/**
 * One row per client, summing only unpaid invoices.
 * Sorted by outstanding amount (descending), then client name (ascending).
 */
export function outstandingByClient(clients: readonly Client[], invoices: readonly Invoice[]): ClientBalance[] {
  const unpaid = invoices.filter(isUnpaid);

  return clients
    .map((client) => {
      const mine = unpaid.filter((invoice) => invoice.clientId === client.id);
      return {
        client,
        outstandingINR: mine.reduce((total, invoice) => total + invoice.amountINR, 0),
        invoiceCount: mine.length,
      };
    })
    .sort(
      (a, b) =>
        b.outstandingINR - a.outstandingINR || a.client.name.localeCompare(b.client.name),
    );
}

/** Follow-ups for one invoice, newest first. */
export function followUpsFor(invoiceId: string, followUps: readonly FollowUp[]): FollowUp[] {
  return followUps
    .filter((followUp) => followUp.invoiceId === invoiceId)
    .sort((a, b) => b.date.localeCompare(a.date));
}

/**
 * An overdue invoice needs a reminder when it has no follow-up
 * dated on or after (today - 14 days).
 */
export function needsReminder(invoice: Invoice, followUps: readonly FollowUp[], today: string): boolean {
  if (invoice.status !== "overdue") {
    return false;
  }
  const windowStart = addDays(today, -REMINDER_WINDOW_DAYS);
  const hasRecent = followUps.some(
    (followUp) => followUp.invoiceId === invoice.id && followUp.date >= windowStart,
  );
  return !hasRecent;
}


